%[text] %[text:anchor:H_733CD629] # Convergence study on transverse shear-locking
%[text:tableOfContents]{"heading":"Table of Contents"}
%[text] In this section it is shown how the rate of the mesh convergence study is reduced down due to transverse shear locking. The effect gets more pronounced the more slender the beam is.
%[text] 
%[text] Go to [THIS](file:./main_Chapter4_TransverseShearLocking_TimoshenkoBeam.mlx:H_D14B8475) Section in the main driver script *Transverse-Shear Locking in Timoshenko beam elements - Cantilever Beam Subject to Vertical Distributed Load*
%[text] Go to [PREVIOUS](file:./main_Chapter41_TimoshenkoBeamLocking_ShearForces.mlx:T_CCE08EC4) Section *Transverse-shear locking due incompatible discretization spaces*
%[text] 
%[text] **Author: Andreas Apostolatos, PhD (aapostol@mathworks.com)**
%[text] **Date: 10.06.2026**
%%
%[text] %[text:anchor:H_7236A159] ## Preamble
vars = ["X0" "XL" "propStr" "numEl" "propStrEB"];
str = "This m-file should be ran from parent m-file " + ...
    "main_Chapter4_TransverseShearLocking_TimoshenkoBeam.mlx";
for ii = 1:length(vars)
    if ~exist(vars(ii), 'var') 
        error(strcat("Variable ", vars(ii), " is not defined. ", str));
    end
end
%%
%[text] %[text:anchor:H_FB28D253] ## Initialize auxiliary arrays
wAnalytical = double(wEx(XL));
tipDeflection = zeros(numEl, 5);
numElmnts = zeros(numEl, 1);
tipDeflectionAnalytical = repmat(wAnalytical, numEl, 1);
%[text] %[text:anchor:H_707313A0] ## Loop over all the refinement levels
for ii = 1:numEl
%[text] %[text:anchor:H_A3FC17F6] ### **One-dimensional linear mesh**
    numElmnts(ii, 1) = ii;
    mshL1Ref = generateLinearMeshOnLine(X0, XL, numElmnts(ii, 1));
    numNodesL1Ref = numel(mshL1Ref.nodes(:, 1));
%[text] %[text:anchor:H_4F9CD37D] ### One-dimensional quadratic mesh
    mshL2Ref = generateQuadraticMeshOnLine(mshL1Ref);
    numNodesL2Ref = numel(mshL2Ref.nodes(:, 1));
%[text] %[text:anchor:H_38972F88] ### Dirichlet boundary conditions for the **one-dimensional linear mesh**
    numDOFsL1ref = 2*numNodesL1Ref;
    freeDOFsL1ref = 1:numDOFsL1ref;
    homDOFsL1ref = 1:2;
    [~, idxL1ref] = ismember(homDOFsL1ref, freeDOFsL1ref);
    freeDOFsL1ref(idxL1ref) = [];
%[text] %[text:anchor:H_D931E29B] ### Dirichlet boundary conditions for the one-dimensional quadratic mesh
    numDOFsL2ref = 2*numNodesL2Ref;
    freeDOFsL2ref = 1:numDOFsL2ref;
    homDOFsL2ref = 1:2;
    [~, idxL2ref] = ismember(homDOFsL2ref, freeDOFsL2ref);
    freeDOFsL2ref(idxL2ref) = [];
%[text] %[text:anchor:H_1AF84604] ### Master stiffness matrix and load vector for the one-dimensional linear mesh using full-integration
    computeStiffMatrixandForceVector = 'undefined';
    computeBasisFunctionsAndDerivs = ...
        @computeLinearBasisFunctionsAndFirstDerivatives;
    dummyInp = 'undefined';
    [KL1ref, FbodyL1ref] = ...
        computeMasterStiffMatrixandForceVectorTimoshenkoBeamPageWise ...
        (mshL1Ref, computeStiffMatrixandForceVector, ...
        computeBasisFunctionsAndDerivs, dummyInp, propStr);
    FL1boundaryref = zeros(2*numNodesL1Ref, 1);
    FL1boundaryref(end - 1, 1) = propStr.Q;
    FL1boundaryref(end, 1) = propStr.M;
    FL1ref = FbodyL1ref + FL1boundaryref;
%[text] %[text:anchor:H_C08C658D] ### Master stiffness matrix and load vector for the one-dimensional linear mesh using selective-reduced integration
    computeStiffMatrixandForceVectorRI = 'undefined';
    computeBasisFunctionsAndDerivs = ...
        @computeLinearBasisFunctionsAndFirstDerivatives;
    dummyInp = 'undefined';
    [KL1RIref, FbodyL1RIref] = ...
        computeMasterStiffMatrixandForceVectorTimoshenkoBeamRIPageWise ...
        (mshL1Ref, computeStiffMatrixandForceVectorRI, ...
        computeBasisFunctionsAndDerivs, dummyInp, propStr);
    FL1boundaryRIref = zeros(2*numNodesL1Ref, 1);
    FL1boundaryRIref(end - 1, 1) = propStr.Q;
    FL1boundaryRIref(end, 1) = propStr.M;
    FL1RIRef = FbodyL1RIref + FL1boundaryRIref;
%[text] %[text:anchor:H_835B2F38] ### Master stiffness matrix and load vector for the one-dimensional quadratic mesh using full-integration
    computeStiffMatrixandForceVector = 'undefined';
    computeBasisFunctionsAndDerivs = ...
        @computeQuadraticBasisFunctionsAndFirstDerivatives;
    dummyInp = 'undefined';
    [KL2Ref, FBodyL2Ref] = ...
        computeMasterStiffMatrixandForceVectorTimoshenkoBeamPageWise ...
        (mshL2Ref, computeStiffMatrixandForceVector, ...
        computeBasisFunctionsAndDerivs, dummyInp, propStr);
    FBoundaryL2Ref = zeros(2*numNodesL2Ref, 1);
    FBoundaryL2Ref(2*numNodesL1Ref - 1, 1) = propStr.Q;
    FBoundaryL2Ref(2*numNodesL1Ref, 1) = propStr.M;
    FL2Ref = FBodyL2Ref + FBoundaryL2Ref;
%[text] %[text:anchor:H_158BC2C3] ### Master stiffness matrix and load vector for the one-dimensional quadratric mesh using selective-reduced integration
    computeStiffMatrixandForceVectorRI = 'undefined';
    computeBasisFunctionsAndDerivs = ...
        @computeQuadraticBasisFunctionsAndFirstDerivatives;
    dummyInp = 'undefined';
    [KL2RIRef, FBodyL2RIRef] = ...
        computeMasterStiffMatrixandForceVectorTimoshenkoBeamRIPageWise ...
        (mshL2Ref, computeStiffMatrixandForceVectorRI, ...
        computeBasisFunctionsAndDerivs, dummyInp, propStr);
    FBoundaryL2RIRef = zeros(2*numNodesL2Ref, 1);
    FBoundaryL2RIRef(2*numNodesL1Ref - 1, 1) = propStr.Q;
    FBoundaryL2RIRef(2*numNodesL1Ref, 1) = propStr.M;
    FL2RIRef = FBodyL2RIRef + FBoundaryL2RIRef;
%[text] %[text:anchor:H_453DFA18] ### Master stiffness matrix and load vector for the one-dimensional linear mesh corresponding to the Euler-Bernoulli formulation using the Hermitian basis functions
    computeStiffMatrixandForceVectorEBT = ...
        @computeElementStiffMatrixandForceVectorEulerBernoulliBeam;
    [KEBRef, FBodyEBRef] = ...
        computeMasterStiffMatrixandForceVectorEulerBernoulliBeam ...
        (mshL1Ref, computeStiffMatrixandForceVectorEBT, propStrEB);
    FBoundaryEBRef = zeros(2*numNodesL1Ref, 1);
    FBoundaryEBRef(end - 1, 1) = propStr.Q;
    FBoundaryEBRef(end, 1) = - propStr.M;
    FEBRef = FBodyEBRef + FBoundaryEBRef;
%[text] %[text:anchor:H_FA6C07A5] ### Initialization of the solution vectors for the one-dimensional linear and quadratic meshes
    uL1Ref = zeros(numDOFsL1ref, 3);
    uL2Ref = zeros(numDOFsL2ref, 2);
%[text] %[text:anchor:H_01DDD254] ### Solve the linear equation system corresponding to the one-dimensional linear mesh using full-integration
    uL1Ref(freeDOFsL1ref, 1) = ...
        KL1ref(freeDOFsL1ref, freeDOFsL1ref)\FL1ref(freeDOFsL1ref);
    tipDeflection(ii, 1) = uL1Ref(end - 1, 1);
%[text] %[text:anchor:H_53F67ACC] ### Solution of the linear equation system corresponding to the one-dimensional linear mesh using selective-reduced integration
    uL1Ref(freeDOFsL1ref, 2) = ...
        KL1RIref(freeDOFsL1ref, freeDOFsL1ref)\FL1RIRef(freeDOFsL1ref);
    tipDeflection(ii, 2) = uL1Ref(end - 1, 2);
%[text] %[text:anchor:H_DBC0C518] ### Solution of the linear equation system corresponding to the one-dimensional quadratic mesh using full-integration
    uL2Ref(freeDOFsL2ref, 1) = ...
        KL2Ref(freeDOFsL2ref, freeDOFsL2ref)\FL2Ref(freeDOFsL2ref);
    [~, idxRef] = sort(mshL2Ref.nodes);
    wL2Ref = uL2Ref(1:2:end, 1);
    tipDeflection(ii, 3) = wL2Ref(idxRef(end), 1);
%[text] %[text:anchor:H_F2B9DE01] ### Solution of the linear equation system corresponding to the one-dimensional quadratic mesh using selective-reduced integration
    uL2Ref(freeDOFsL2ref, 2) = ...
        KL2RIRef(freeDOFsL2ref, freeDOFsL2ref)\FL2RIRef(freeDOFsL2ref);
    [~, idxRIRef] = sort(mshL2Ref.nodes);
    wL2RIRef = uL2Ref(1:2:end, 2);
    tipDeflection(ii, 4) = wL2RIRef(idxRIRef(end), 1);
%[text] %[text:anchor:H_C27B4332] ### Solution of the linear equation system corresponding to the Euler-Bernoulli beam theory on the one-dimensional linear mesh using the Hermitian basis functions
    uL1Ref(freeDOFsL1ref, 3) = ...
        KEBRef(freeDOFsL1ref, freeDOFsL1ref)\FEBRef(freeDOFsL1ref);
    tipDeflection(ii, 5) = uL1Ref(end - 1, 3);
%[text] %[text:anchor:H_AEE9064B] #### 
end
%%
%[text] %[text:anchor:H_F41A9C84] ## Plot the convergence graph
plot(numElmnts, abs(tipDeflection(:, 1)), "-bo", LineWidth=2) %[output:69fdff99]
hold on; %[output:69fdff99]
plot(numElmnts, abs(tipDeflection(:, 2)), "-.bv", LineWidth=2) %[output:69fdff99]
plot(numElmnts, abs(tipDeflection(:, 3)), "-ro", LineWidth=2) %[output:69fdff99]
plot(numElmnts, abs(tipDeflection(:, 4)), "-.rv", LineWidth=2) %[output:69fdff99]
plot(numElmnts, abs(tipDeflection(:, 5)), "-mo", LineWidth=2) %[output:69fdff99]
plot(numElmnts, abs(tipDeflectionAnalytical), "-k", LineWidth=2) %[output:69fdff99]
hold off; %[output:69fdff99]
grid on; %[output:69fdff99]
legend("L1", "L1 reduced", "L2", "L2 reduced", "E/B", "analytical", ... %[output:69fdff99]
    Location="best") %[output:69fdff99]
xlabel("No. elements") %[output:69fdff99]
ylabel("$w (x = L)$", "Interpreter","latex") %[output:69fdff99]
title("Convergence of the tip displacement of the beam", ... %[output:group:10431a39] %[output:69fdff99]
    "Interpreter", "latex") %[output:group:10431a39] %[output:69fdff99]
